func sdkToolAnnotations(raw any) (*mcpsdk.ToolAnnotations, error) {
	if raw == nil {
		return nil, nil
	}
	data, err := json.Marshal(raw)
	if err != nil {
		return nil, err
	}
	var annotations mcpsdk.ToolAnnotations
	if err := json.Unmarshal(data, &annotations); err != nil {
		return nil, err
	}
	return &annotations, nil
}
func sdkToolInputSchema(raw string) any {
	if raw == "" {
		return jsontext.Value("{\"type\":\"object\"}")
	}
	return jsontext.Value([]byte(raw))
}
func sdkToolFromToolInfo(tool *ToolInfo) (*mcpsdk.Tool, error) {
	if tool == nil {
		return nil, fmt.Errorf("nil MCP tool info")
	}
	annotations, err := sdkToolAnnotations(tool.Annotations)
	if err != nil {
		return nil, err
	}
	meta, err := sdkMeta(tool.Meta)
	if err != nil {
		return nil, err
	}
	sdkTool := &mcpsdk.Tool{
		Annotations:  annotations,
		Description:  derefString(tool.Description),
		InputSchema:  tool.InputSchema,
		Meta:         meta,
		Name:         tool.Name,
		OutputSchema: tool.OutputSchema,
		Title:        derefString(tool.Title),
	}
	if len(tool.Icons) > 0 {
		sdkTool.Icons = make([]mcpsdk.Icon, 0, len(tool.Icons))
		for _, icon := range tool.Icons {
			sdkIcon := mcpsdk.Icon{
				MIMEType: derefString(icon.MimeType),
				Sizes:    icon.Sizes,
				Source:   icon.Src,
				Theme:    mcpsdk.IconTheme(derefString(icon.Theme)),
			}
			sdkTool.Icons = append(sdkTool.Icons, sdkIcon)
		}
	}
	return sdkTool, nil
}
func (a *MCPAdapter) sdkHandlerContext() sdkbridge.HandlerContext {
	return sdkbridge.HandlerContext{
		RequestStateKey: a.requestStateKey,
		Sessions:        a.sessions,
	}
}
func (a *MCPAdapter) sdkToolHandler() mcpsdk.ToolHandler {
	return sdkbridge.ToolHandler(a.sdkHandlerContext(), func(ctx context.Context, request sdkbridge.ToolRequest) (*mcpsdk.CallToolResult, error) {
		payload := &ToolsCallPayload{
			Arguments: mcpJSONFromRaw(request.Arguments),
			Name:      request.Name,
		}
		ctx = request.Bind(payload)
		result, err := a.ToolsCall(ctx, payload)
		if err != nil {
			return nil, err
		}
		return sdkCallToolResult(result)
	})
}
func sdkCallToolResult(result *ToolsCallResult) (*mcpsdk.CallToolResult, error) {
	if result == nil {
		return &mcpsdk.CallToolResult{Content: []mcpsdk.Content{}}, nil
	}
	content := make([]mcpsdk.Content, 0, len(result.Content))
	for _, item := range result.Content {
		converted, err := sdkContentFromItem(item)
		if err != nil {
			return nil, err
		}
		content = append(content, converted)
	}
	callResult := &mcpsdk.CallToolResult{Content: content}
	structuredContent, err := mcpJSONRaw(result.StructuredContent)
	if err != nil {
		return nil, err
	}
	if len(structuredContent) > 0 {
		callResult.StructuredContent = structuredContent
	}
	if result.IsError != nil {
		callResult.IsError = *result.IsError
	}
	return callResult, nil
}
func sdkContentFromItem(item *ContentItem) (mcpsdk.Content, error) {
	if item == nil {
		return &mcpsdk.TextContent{}, nil
	}
	meta, err := sdkMeta(item.Meta)
	if err != nil {
		return nil, err
	}
	switch item.Type {
	case "text":
		return &mcpsdk.TextContent{
			Meta: meta,
			Text: derefString(item.Text),
		}, nil
	case "image":
		data, err := sdkDecodeBase64(item.Data)
		if err != nil {
			return nil, err
		}
		return &mcpsdk.ImageContent{
			Data:     data,
			MIMEType: derefString(item.MimeType),
			Meta:     meta,
		}, nil
	case "audio":
		data, err := sdkDecodeBase64(item.Data)
		if err != nil {
			return nil, err
		}
		return &mcpsdk.AudioContent{
			Data:     data,
			MIMEType: derefString(item.MimeType),
			Meta:     meta,
		}, nil
	case "resource":
		resource, err := sdkResourceContents(item, meta)
		if err != nil {
			return nil, err
		}
		return &mcpsdk.EmbeddedResource{
			Meta:     meta,
			Resource: resource,
		}, nil
	default:
		if item.URI != nil {
			resource, err := sdkResourceContents(item, meta)
			if err != nil {
				return nil, err
			}
			return &mcpsdk.EmbeddedResource{
				Meta:     meta,
				Resource: resource,
			}, nil
		}
		return nil, fmt.Errorf("unsupported MCP content type %q", item.Type)
	}
}
func sdkResourceContents(item *ContentItem, meta mcpsdk.Meta) (*mcpsdk.ResourceContents, error) {
	resource := &mcpsdk.ResourceContents{
		MIMEType: derefString(item.MimeType),
		Meta:     meta,
		Text:     derefString(item.Text),
		URI:      derefString(item.URI),
	}
	if item.Data != nil {
		data, err := sdkDecodeBase64(item.Data)
		if err != nil {
			return nil, err
		}
		resource.Blob = data
	}
	return resource, nil
}
func sdkMeta(value any) (mcpsdk.Meta, error) {
	return sdkbridge.DecodeMeta(value)
}
func sdkDecodeBase64(raw *string) ([]byte, error) {
	if raw == nil || *raw == "" {
		return nil, nil
	}
	data, err := base64.StdEncoding.DecodeString(*raw)
	if err != nil {
		return nil, err
	}
	return data, nil
}
func derefString(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}
func boolPtr(v bool) *bool {
	return &v
}
